import math

SR = 16000
N_FFT = 400
HOP = 160
CHUNK_SECONDS = 30


def hz_to_mel(f):
    return 2595.0 * math.log10(1.0 + f / 700.0)


def mel_to_hz(m):
    return 700.0 * (10.0 ** (m / 2595.0) - 1.0)


def pad_or_trim(audio, length):
    if len(audio) >= length:
        return list(audio[:length])
    return list(audio) + [0.0] * (length - len(audio))


def frame_count(samples, hop=HOP):
    return samples // hop


def front_end_shape(n_mels=80, sr=SR, hop=HOP, seconds=CHUNK_SECONDS):
    return (n_mels, frame_count(sr * seconds, hop))


def mel_filterbank(sr=SR, n_fft=N_FFT, n_mels=80):
    top = hz_to_mel(sr / 2)
    points = [i * top / (n_mels + 1) for i in range(n_mels + 2)]
    bins = [int(math.floor((n_fft + 1) * mel_to_hz(p) / sr)) for p in points]
    width = n_fft // 2 + 1
    bank = [[0.0] * width for _ in range(n_mels)]
    for m in range(1, n_mels + 1):
        low, centre, high = bins[m - 1], bins[m], bins[m + 1]
        for k in range(low, min(centre, width)):
            bank[m - 1][k] = (k - low) / max(centre - low, 1)
        for k in range(centre, min(high, width)):
            bank[m - 1][k] = (high - k) / max(high - centre, 1)
    return bank


def normalize(energies):
    logs = [math.log10(max(value, 1e-10)) for value in energies]
    ceiling = max(logs)
    floored = [max(value, ceiling - 8.0) for value in logs]
    return [(value + 4.0) / 4.0 for value in floored]
